(async () => {
  const m = window.__mymechanics; const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  if (m.state.editing) m.actions.cancelEditing({ quiet: true });
  await m.actions.closeProject({ force: true });
  await m.actions.openSampleAsk('asmViceDrawing'); await sleep(2500);
  const d = m.active();
  const before = (d.annotations ?? []).filter((a) => a.kind === 'balloon' && a.auto).length;
  await m.run('drwAutoBalloon'); await sleep(800);
  const { bomRows } = await import('/src/cad/drawing.js');
  const asm = m.project.assemblies.find((a) => a.id === d.source.id);
  const rows = bomRows(asm, m.project).length;
  const balloons = (m.active().annotations ?? []).filter((a) => a.kind === 'balloon' && a.auto);
  let minGap = Infinity;
  for (let i = 0; i < balloons.length; i++) for (let j = i + 1; j < balloons.length; j++) minGap = Math.min(minGap, Math.hypot(balloons[i].x - balloons[j].x, balloons[i].y - balloons[j].y));
  const items = new Set(balloons.map((b) => b.item)).size;
  return JSON.stringify({ before, all: balloons.length === rows, items: items === rows, apart: minGap >= 12 });
})()

