(async () => {
  const m = window.__mymechanics; const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  if (m.state.editing) m.actions.cancelEditing({ quiet: true });
  await m.actions.closeProject({ force: true });
  await m.actions.openSampleAsk('basMountBracket'); await sleep(1500);
  const faces = m.state.partEntry.faces;
  const pick = (test) => { const index = faces.findIndex(test); return { kind: 'face', bodyKey: 'body', index, key: `face:body:${index}` }; };
  const n = (f) => { const v = f.normalAt(); return [v.x, v.y, v.z]; };
  const top = pick((f) => f.geomType === 'PLANE' && Math.abs(n(f)[2] - 1) < 1e-6);
  const side = pick((f) => f.geomType === 'PLANE' && Math.abs(n(f)[0] - 1) < 1e-6);
  m.state.selection = [top, side];
  await m.run('relativeView'); await sleep(2500);
  const d = m.active();
  const v = d.views?.find((x) => x.type === 'custom');
  await m.run('removedSection'); await sleep(2000);
  const r = m.active().views.find((x) => x.kind === 'section' && x.removed);
  const svg = document.querySelector('#drawing-host svg')?.innerHTML ?? '';
  return JSON.stringify({ drawing: Boolean(d?.views), relative: v ? v.dir.map(Math.round).join(',') + '|' + v.x.map(Math.round).join(',') : 'none', removed: Boolean(r), drawn: svg.length > 1000 });
})()
